contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        uint beforeBalance = address(c).balance;
        bool revertsNoCredit;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertsNoCredit = true; } else { revertsNoCredit = false; }
        uint afterNoCredit = address(c).balance;

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint afterDeposit = address(c).balance;

        bool revertsWithCredit;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertsWithCredit = true; } else { revertsWithCredit = false; }
        uint afterWithdrawal = address(c).balance;

        assert(
            !revertsNoCredit &&
            afterNoCredit == beforeBalance &&
            afterDeposit == beforeBalance + depositAmount &&
            !revertsWithCredit &&
            afterWithdrawal == afterDeposit - depositAmount &&
            afterWithdrawal == beforeBalance
        );
    }

    receive() external payable {}
}

