pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeBalance = address(c).balance;
        bool revertsNoCredit;
        try c.withdrawAll() { revertsNoCredit = false; } catch { revertsNoCredit = true; }
        uint afterNoCredit = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDeposit = address(c).balance;
        bool revertsWithCredit;
        try c.withdrawAll() { revertsWithCredit = false; } catch { revertsWithCredit = true; }
        uint afterWithdrawal = address(c).balance;
        assertTrue(!revertsNoCredit &&
            afterNoCredit == beforeBalance &&
            afterDeposit == beforeBalance + depositAmount &&
            !revertsWithCredit &&
            afterWithdrawal == afterDeposit - depositAmount &&
            afterWithdrawal == beforeBalance);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
